// Copies the print agents (agent/label_agent.py and agent/windows/label-agent.ps1) into src/agent-files.js, so the
// worker can serve them to the computers that install or update them. Run after changing either agent:
//   node demo/embed-agent.mjs        (npm run embed-agent)
// web/test/labelstation.test.mjs fails when the embedded copies and the files differ.
import { readFileSync, writeFileSync } from "node:fs";

const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
export const embedded = () =>
  "// Generated by demo/embed-agent.mjs from agent/ (do not edit here): the print agents the label station serves.\n" +
  `export const AGENT_PY = ${JSON.stringify(read("../../agent/label_agent.py"))};\n` +
  `export const AGENT_PS1 = ${JSON.stringify(read("../../agent/windows/label-agent.ps1"))};\n`;

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(new URL("../src/agent-files.js", import.meta.url), embedded());
  console.log("src/agent-files.js");
}
